22	/**
23	 * Drive the create-flow PDS login via the native in-app auth session (ASWebAuthenticationSession
24	 * on iOS, via the auth-session plugin). Three steps: `prepare_oauth_flow` (Rust) does PKCE + PAR
25	 * and returns the authorize URL; the plugin opens the in-app session and returns the
26	 * custom-scheme callback URL; `complete_oauth_flow` (Rust) validates the CSRF state and exchanges
27	 * the code for tokens. The PKCE verifier and CSRF state never leave the Rust backend — only the
28	 * authorize URL and (briefly) the callback URL transit the webview.
29	 *
30	 * An in-app session is required because iOS Safari will not auto-launch the app from a
31	 * server-side redirect to a custom URL scheme.
32	 *
33	 * `loginHint` (optional) pre-populates the authorize page's identifier field. The create flow
34	 * passes the handle it just registered so the user doesn't retype it — the server renders it into
35	 * the identifier `<input>` (`value="…" autocomplete="username"`).
36	 */
37	export const startOAuthFlow = async (loginHint?: string): Promise<void> => {
38	  const prepared = await invoke<{ authUrl: string; callbackScheme: string }>('prepare_oauth_flow', {
39	    loginHint: loginHint ?? null,
40	  });
41	  let callbackUrl: string;
42	  try {
43	    callbackUrl = await invoke<string>('plugin:auth-session|start', {
44	      authUrl: prepared.authUrl,
45	      callbackUrlScheme: prepared.callbackScheme,
46	    });
47	  } catch {
48	    // The auth-session plugin rejects with a plain string ("user_cancelled", "Invalid auth
49	    // URL: ..."), not the OAuthError shape. Normalize so the UI's error handling stays uniform;
50	    // a dismissed sheet reads as an abandoned callback.
51	    throw { code: 'CALLBACK_ABANDONED' } as OAuthError;
52	  }
53	  await invoke('complete_oauth_flow', { callbackUrl });
54	};
